using System;
using System.Globalization;
using CargoWise.RefDbRepo.Common.DbUpgrade;
using NUnit.Framework;

namespace CargoWise.RefDbRepo.Staging.DbUpgrader.Test
{
	[Property("DAT:CapabilityRequirements", "SQL2019+")]
	class QuartzJobTypeTransformationFixture : TransformationFixture
	{
		protected override void AssertTransformationResults()
		{
			using (var cmd = Connection.CreateCommand())
			{
				cmd.Transaction = Transaction;
				cmd.CommandText = @"SELECT COUNT(*) FROM QRTZ_JOB_DETAILS";
				Assert.AreEqual(Convert.ToInt32(cmd.ExecuteScalar(), CultureInfo.InvariantCulture), 4);
				cmd.CommandText = @"SELECT COUNT(*) FROM QRTZ_JOB_DETAILS WHERE JOB_CLASS_NAME = 'CargoWise.RefDbRepo.Staging.Schedulers.Common.QuartzAppRunner, CargoWise.RefDbRepo.Staging.Schedulers.Common'";
				Assert.AreEqual(Convert.ToInt32(cmd.ExecuteScalar(), CultureInfo.InvariantCulture), 1);
				cmd.CommandText = @"SELECT COUNT(*) FROM QRTZ_JOB_DETAILS WHERE JOB_CLASS_NAME = 'CargoWise.RefDbRepo.Staging.Schedulers.Common.QuartzDataUpdater, CargoWise.RefDbRepo.Staging.Schedulers.Common'";
				Assert.AreEqual(Convert.ToInt32(cmd.ExecuteScalar(), CultureInfo.InvariantCulture), 1);
				cmd.CommandText = @"SELECT COUNT(*) FROM QRTZ_JOB_DETAILS WHERE JOB_CLASS_NAME = 'CargoWise.RefDbRepo.Staging.Schedulers.Common.QuartzProcessorRunner, CargoWise.RefDbRepo.Staging.Schedulers.Common'";
				Assert.AreEqual(Convert.ToInt32(cmd.ExecuteScalar(), CultureInfo.InvariantCulture), 1);
				cmd.CommandText = @"SELECT COUNT(*) FROM QRTZ_JOB_DETAILS WHERE JOB_CLASS_NAME = 'CargoWise.RefDbRepo.Staging.Schedulers.Common.SingleInstanceQuartzAppRunner, CargoWise.RefDbRepo.Staging.Schedulers.Common'";
				Assert.AreEqual(Convert.ToInt32(cmd.ExecuteScalar(), CultureInfo.InvariantCulture), 1);
			}
		}

		protected override IDataTransformationTask GetTask()
		{
			return new QuartzJobTypeTransformationTask(200);
		}

		protected override void PrepareTestData()
		{
			using (var cmd = Connection.CreateCommand())
			{
				cmd.CommandText = @"
INSERT INTO [dbo].[QRTZ_JOB_DETAILS]([JOB_PK],[SCHED_NAME],[JOB_NAME],[JOB_GROUP],[DESCRIPTION],[JOB_CLASS_NAME],[IS_DURABLE],[IS_NONCONCURRENT],[IS_UPDATE_DATA],[REQUESTS_RECOVERY],[JOB_DATA])
values
('E5272860-D596-4BFA-8D1A-00F42777026A','RefDbRepoQuartzServer','AF Exchange Rate','DEFAULT',NULL,'CargoWise.RefDbRepo.Staging.Schedulers.QuartzAppRunner, CargoWise.RefDbRepo.Staging.Schedulers',1,1,0,0,),
('E5272860-D596-4BFA-8D1A-00F42777026B','RefDbRepoQuartzServer','BF Exchange Rate','DEFAULT',NULL,'CargoWise.RefDbRepo.Staging.Schedulers.QuartzDataUpdater, CargoWise.RefDbRepo.Staging.Schedulers',1,1,0,0,),
('E5272860-D596-4BFA-8D1A-00F42777026C','RefDbRepoQuartzServer','CF Exchange Rate','DEFAULT',NULL,'Cargowise.RefDbRepo.Staging.Schedulers.QuartzProcessorRunner, Cargowise.RefDbRepo.Staging.Schedulers',1,1,0,0,),
('E5272860-D596-4BFA-8D1A-00F42777026E','RefDbRepoQuartzServer','DF Exchange Rate','DEFAULT',NULL,'Cargowise.RefDbRepo.Staging.Schedulers.SingleInstanceQuartzAppRunner, Cargowise.RefDbRepo.Staging.Schedulers',1,1,0,0,)
";
				cmd.Transaction = Transaction;
				cmd.ExecuteNonQuery();
			}
		}
	}
}
